package dev.zomboidmelee.boxing;
public final class StompClient21{
 public static void begin(Object p,int kind,boolean confirmed){if(kind!=Motion20.STOMP)return;Client20.State s=Client20.state(p);s.resolved=0;s.hit=false;s.reach=.70;s.height=.20;s.side=.08;Object m=BoxingClient16.mc();if(p==R.get(m,"player")){try{Object h=StompTarget21.target(m),q=R.call(h,"getLocation");s.target=R.call(h,"getType").toString().equals("ENTITY")?((Number)R.call(R.call(h,"getEntity"),"getId")).intValue():-1;double dx=R.num(R.get(q,"x"))-R.num(R.call(p,"getX")),dz=R.num(R.get(q,"z"))-R.num(R.call(p,"getZ")),yaw=Math.toRadians(R.num(R.call(p,"getYRot")));s.reach=Math.max(.45,Math.min(1.05,-Math.sin(yaw)*dx+Math.cos(yaw)*dz));s.side=Math.max(-.18,Math.min(.22,Math.cos(yaw)*dx+Math.sin(yaw)*dz));s.height=Math.max(0,Math.min(.65,R.num(R.get(q,"y"))-R.num(R.call(p,"getY"))));}catch(IllegalStateException noPoint){}if(!confirmed)R.call(p,"playSound",R.get(R.type("net.minecraft.sounds.SoundEvents"),"PLAYER_ATTACK_SWEEP"),.35f,.80f);}}
 public static double phase(Client20.State s,long now,double raw){if(s.resolved==0){if(raw<1.8)return Math.min(raw,StompMotion21.HOLD);return Math.min(1,.80+(raw-1.8));}if(now<s.resolved)return Math.min(raw,StompMotion21.PLANT);return Math.min(1,StompMotion21.PLANT+(now-s.resolved)/(StompMotion21.DURATION*(1-StompMotion21.PLANT)));}
 public static boolean receive(Object p,int action){Client20.State s=Client20.state(p);if(s.kind!=Motion20.STOMP)return action==20||action==21;if(action==20){s.start=0;s.contact=0;return true;}if(action==18||action==21){s.resolved=Math.max(Client20.now(),s.start+(long)(StompMotion21.PLANT*StompMotion21.DURATION));s.hit=action==18;s.contact=s.hit?s.resolved:0;return true;}return false;}
 public static void camera(Object e,Object p,double phase){Client20.State s=Client20.state(p);double lift=StompMotion21.lift(phase),press=StompMotion21.stamp(phase),impact=s.hit?StompMotion21.contactWave((Client20.now()-s.contact)/1e9):0;Look21.apply(e,p,s,phase);double pitch=-.55*lift+.75*press+2.4*impact,roll=-.32*lift+.16*press+.32*impact;R.call(e,"setPitch",((Number)R.call(e,"getPitch")).floatValue()+(float)pitch);R.call(e,"setRoll",((Number)R.call(e,"getRoll")).floatValue()+(float)roll);}
}
